Method.Source:
/// <summary>
/// designed from AVA
/// </summary>
public void postLoad()
{
    next postLoad();

    CustInvoiceJour         custInvoiceJour;
    SalesTable              salesTable;

    select firstonly custInvoiceJour
       where custInvoiceJour.InvoiceId   == this.InvoiceId
          && custInvoiceJour.InvoiceDate == this.InvoiceDate;

    salesTable = SalesTable::find(custInvoiceJour.SalesId);

    this.AVARemainAmountToBePaid = custInvoiceJour.remainAmountToBePaid();
    this.AVARepPckSlipDate       = salesTable.AVARepPckSlipDate;
    this.AVARepPckSlipNum        = salesTable.AVARepPckSlipNum;
    this.KCS_SOCDueDateExtension = custInvoiceJour.InvoiceDate + this.AVAValutaExtensionDays;
    this.AVAEDICommissionId      = salesTable.avaEDISalesTableOrig().NDXEDICommissionId;

    this.AVAWeight               = salesTable.avaGetGrossWeightRemaining();


}
